# Write all checklists to data/fssai_checklists/
os.makedirs('data/fssai_checklists', exist_ok=True)
for cat, items in checklists.items():
    slug = cat.lower().replace('&', 'and').replace(' ', '_')
    path = f'data/fssai_checklists/{slug}.json'
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(items, f, indent=2, ensure_ascii=False)
    pts = sum(x['weight'] for x in items)
    print(f'Wrote {path}: {len(items)} items, {pts} total points')

# Also write master index
with open('data/fssai_checklists/checklists_index.json', 'w', encoding='utf-8') as f:
    json.dump({k: {'items': len(v), 'total_points': sum(x['weight'] for x in v)} for k, v in checklists.items()}, f, indent=2)

print('Checklist parsing and storage complete!')
